/**
 * Klasse zur Implementation eines Mosaiks.
 * 
 * Suche (STRG + F) nach "TODO" und ergänze den Code. 
 */
public class Graph
{
   Knoten[] knoten;
   boolean [][] adja; 

   // Wird vorläufig einfach festgesetzt. 
   int anzKnoten = 5; 


    /**
     * Konstruktor für Objekte der Klasse Mosaik.
     */
   Graph()
   {
      // TODO 1: Initialisiere knoten und adja


      // Um knoten anschließend mit passenden Objekten zu befüllen. 
      // Dies ist für adja nicht nötig, da boolean automatisch mit "false" initialisiert wird.
      for (int i = 0; i < knoten.length; i++) {
         knoten[i] = new Knoten(); 
         knoten[i].setKnotenname((String)i);
         // nur für die graphische Darstellung
         knoten[i].moveTo(100 + ((i % 3 * 200)), 100 + (i * 100));
      }
   }

    /**
     * Diese Methode fügt der Adjazenzmatrix eine Kante von start nach ende hinzu. 
     */
   void kanteHinzufügen(int start, int ende) 
   {
      //TODO 2: Übertrage die Methode von deinem Arbeitsblatt und ergänze sie wenn nötig. 


      // ist dies nun ein gerichteter oder ungerichteter Graph, basierend auf der Methode vom Blatt? 
      zeichneKante(start, ende);
      printAdja();
   } 


   /**
    * Methode um die Adjazenzmatrix auf der Konsole auszugeben. 
    */
   void printAdja() {
      // TODO Ergänze die Methode. du benötigst hierzu 
      // zwei geschachtelte Wiederholungen mit fester Anzahl. 
      // eine ist bereits vorhanden. 
      for (int x = 0; x < anzKnoten; x++) {
         int y = 0; // Ersetze dies mit der zweiten Wiederholung
         if(adja[x][y]) {
            print("X ");
         } else {
            print("O ");
         }
         if(y == anzKnoten - 1) {
            println();
         }

      }
   }



   void zeichneKante(int start, int ende) {
      double startX = knoten[start].getCenterX(); 
      double startY = knoten[start].getCenterY();

      double endeX = knoten[ende].getCenterX();
      double endeY = knoten[ende].getCenterY();

      double abstand = Vector2.distance(startX, startY, endeX, endeY);

      double winkel = new Vector2(endeX - startX, endeY - startY).getAngleDeg(); 

      Rectangle rectangle = new Rectangle(startX, startY, 10, abstand);
      rectangle.setFillColor(Color.white);
      rectangle.setAlpha(0.6); 
      rectangle.rotate(90 - winkel, startX, startY);

      //some troubleshooting calls
      println("Start: " + start + " startX: " + startX + " startY: " + startY); 
      println("Ende: " + ende + " endeX: " + endeX + " endeY: " + endeY);
      println("Abstand: " + abstand);
      println("Winkel: " + winkel);
      println();

   }
}

class Knoten extends Sprite {
   private String knotenname = "Knoten X"; 

   Knoten() {
      super(0,0, SpriteLibrary.PMan, 2);
   }

   String getKnotenname() {
      return knotenname; 
   }

   void setKnotenname(String _knotenname) {
      knotenname = _knotenname; 
   }
}
